//! `locora.toml`: memory palaces as source files.
//!
//! A palace can be written by hand, kept in Git or generated by scripts and
//! AI, then built into the local store with `locora build`. `locora dump`
//! writes an existing palace back as source plus its media files.
//!
//! ```toml
//! name = "Planeten"
//!
//! [[room]]
//! name = "Wohnung"
//! image = "wohnung.jpg"
//! items = ["Merkur", "Venus", "Erde"]
//!
//! [[room.locus]]
//! place = "Herd"
//! item = "Mars"
//! at = [0.4, 0.6]
//! answer = "guess"
//! ```

pub mod places;

use std::collections::{BTreeMap, HashMap};
use std::fs;
use std::path::{Path, PathBuf};

use locora_api::journey::{Answer, AnswerKind, QuizOption};
use locora_formula::workbook::{Binding, BindingField};
use locora_formula::{Cell, CellType, Row};
use locora_store::{NewLocus, PalaceTree, RoomKind, Store};
use serde::{Deserialize, Serialize};

#[derive(Debug, thiserror::Error)]
pub enum SourceError {
    #[error("{0}")]
    Invalid(String),
    #[error("TOML: {0}")]
    Toml(#[from] toml::de::Error),
    #[error("{0}: {1}")]
    File(String, std::io::Error),
    #[error(transparent)]
    Store(#[from] locora_store::StoreError),
}

pub type Result<T, E = SourceError> = std::result::Result<T, E>;

fn invalid(message: impl Into<String>) -> SourceError {
    SourceError::Invalid(message.into())
}

// ---------------------------------------------------------------- source model

/// A palace as written in `locora.toml`.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Source {
    pub name: String,
    /// Custom locus marker (`.sply`), relative to the source file; default marker if missing.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub marker: Option<String>,
    #[serde(default, rename = "room", skip_serializing_if = "Vec::is_empty")]
    pub rooms: Vec<RoomSource>,
    #[serde(default, rename = "table", skip_serializing_if = "Vec::is_empty")]
    pub tables: Vec<TableSource>,
}

#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RoomSource {
    pub name: String,
    /// Backdrop image, relative to the source file.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub image: Option<String>,
    /// Backdrop video, relative to the source file.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub video: Option<String>,
    /// Short form: one locus per item, placed automatically along a route.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub items: Vec<String>,
    #[serde(default, rename = "locus", skip_serializing_if = "Vec::is_empty")]
    pub loci: Vec<LocusSource>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct LocusSource {
    /// Picture width as a fraction of the room width (0.05..=1.0).
    #[serde(default = "locora_store::default_image_size")]
    pub image_size: f64,
    /// Zoom on the locus while asking, 1 (whole room, default) to 4.
    #[serde(
        default = "locora_store::default_zoom",
        skip_serializing_if = "whole_room"
    )]
    pub zoom: f64,
    /// The place in the room (default „Ort N“).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub place: Option<String>,
    pub item: String,
    /// Position `[x, y]`, each 0..1 (default: automatic route).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub at: Option<[f64; 2]>,
    /// Video time: seconds or `"m:ss"`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub time: Option<TimeSource>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub answer: Option<AnswerSource>,
    /// Picture shown at the locus: an image or a `.sply` animation, relative to the source file.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub image: Option<String>,
    /// Memory aid shown after the answer.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub note: Option<String>,
    /// Formulas per field: place, item, x, y, visible, active.
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub bindings: BTreeMap<String, String>,
}

fn whole_room(zoom: &f64) -> bool {
    *zoom == locora_store::default_zoom()
}

impl Default for LocusSource {
    fn default() -> Self {
        Self {
            image_size: locora_store::default_image_size(),
            zoom: locora_store::default_zoom(),
            place: None,
            item: String::new(),
            at: None,
            time: None,
            answer: None,
            image: None,
            note: None,
            bindings: BTreeMap::new(),
        }
    }
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(untagged)]
pub enum TimeSource {
    Seconds(f64),
    Clock(String),
}

/// `"recall"`, `"guess"` or a quiz table.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(untagged)]
pub enum AnswerSource {
    Kind(String),
    Quiz(QuizSource),
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct QuizSource {
    #[serde(rename = "type")]
    pub kind: String,
    /// Short form: right answers first, then wrong ones.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub correct: Vec<String>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub wrong: Vec<String>,
    /// Long form with an explicit order.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub options: Vec<QuizOption>,
    /// Guess: further answers that also count as right.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub accept: Vec<String>,
}

/// A table row: short form `value` (+ `type`) or explicit `cells`.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct TableSource {
    pub table: String,
    pub key: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub value: Option<String>,
    #[serde(default, rename = "type", skip_serializing_if = "Option::is_none")]
    pub kind: Option<CellType>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub cells: Vec<Cell>,
}

// ---------------------------------------------------------------- conversions

/// Parse `m:ss`, `h:mm:ss` or plain seconds.
pub fn parse_time(text: &str) -> Option<f64> {
    let parts: Vec<&str> = text.trim().split(':').collect();
    if parts.len() > 3 || parts.iter().any(|p| p.is_empty()) {
        return None;
    }
    let mut seconds = 0.0;
    for part in &parts {
        seconds = seconds * 60.0
            + part
                .parse::<f64>()
                .ok()
                .filter(|v| v.is_finite() && *v >= 0.0)?;
    }
    Some(seconds)
}

/// Image or video by file extension: (room kind, media type).
pub fn media_type(path: &Path) -> Option<(RoomKind, &'static str)> {
    let ext = path.extension()?.to_str()?.to_ascii_lowercase();
    Some(match ext.as_str() {
        "png" => (RoomKind::Image, "image/png"),
        "jpg" | "jpeg" => (RoomKind::Image, "image/jpeg"),
        "webp" => (RoomKind::Image, "image/webp"),
        "gif" => (RoomKind::Image, "image/gif"),
        "avif" => (RoomKind::Image, "image/avif"),
        "mp4" | "m4v" => (RoomKind::Video, "video/mp4"),
        "webm" => (RoomKind::Video, "video/webm"),
        "mov" => (RoomKind::Video, "video/quicktime"),
        "sply" => (RoomKind::Image, locora_store::SPLINELY),
        _ => return None,
    })
}

const SPLY_MAGIC: &[u8] = b"\x89SPLY\r\n\x1a";

/// A picture file for a locus: an image or a `.sply` animation that exists.
fn check_picture(base: &Path, file: &str, where_: &str) -> Result<(PathBuf, &'static str)> {
    let path = base.join(file);
    let (kind, media_type) = media_type(&path).ok_or_else(|| {
        invalid(format!(
            "{where_}: {file}: unbekanntes Format (png, jpg, webp, gif, avif, sply)"
        ))
    })?;
    if kind != RoomKind::Image {
        return Err(invalid(format!(
            "{where_}: {file}: ein Locus-Bild kann kein Video sein"
        )));
    }
    check_file(&path, media_type, where_)?;
    Ok((path, media_type))
}

/// The file exists; `.sply` files must really be binary Splinely projects.
fn check_file(path: &Path, media_type: &str, where_: &str) -> Result<()> {
    if !path.is_file() {
        return Err(invalid(format!("{where_}: Datei {} fehlt", path.display())));
    }
    if media_type == locora_store::SPLINELY {
        let mut head = [0u8; 8];
        let ok = fs::File::open(path)
            .and_then(|mut f| std::io::Read::read_exact(&mut f, &mut head))
            .is_ok();
        if !ok || head != SPLY_MAGIC {
            return Err(invalid(format!(
                "{where_}: {} ist keine binäre .sply-Datei (mit `splinely-cli convert` umwandeln)",
                path.display()
            )));
        }
    }
    Ok(())
}

fn extension_of(media_type: &str) -> &'static str {
    match media_type {
        "image/png" => "png",
        "image/jpeg" => "jpg",
        "image/webp" => "webp",
        "image/gif" => "gif",
        "image/avif" => "avif",
        "video/mp4" => "mp4",
        "video/webm" => "webm",
        "video/quicktime" => "mov",
        locora_store::SPLINELY => "sply",
        _ => "bin",
    }
}

impl AnswerSource {
    fn to_answer(&self, where_: &str) -> Result<Answer> {
        let answer = match self {
            AnswerSource::Kind(kind) => match kind.as_str() {
                "recall" => Answer::default(),
                "guess" => Answer {
                    kind: AnswerKind::Guess,
                    ..Answer::default()
                },
                "quiz" => {
                    return Err(invalid(format!(
                        "{where_}: Quiz braucht `correct` und `wrong` oder `options`"
                    )));
                }
                other => {
                    return Err(invalid(format!(
                        "{where_}: unbekannte Antwortart „{other}“ (recall, guess, quiz)"
                    )));
                }
            },
            AnswerSource::Quiz(guess) if guess.kind == "guess" => {
                if !guess.correct.is_empty() || !guess.wrong.is_empty() || !guess.options.is_empty()
                {
                    return Err(invalid(format!(
                        "{where_}: Guess kennt nur `accept`, keine Quizoptionen"
                    )));
                }
                Answer {
                    kind: AnswerKind::Guess,
                    accept: guess.accept.clone(),
                    ..Answer::default()
                }
            }
            AnswerSource::Quiz(quiz) => {
                if quiz.kind != "quiz" {
                    return Err(invalid(format!(
                        "{where_}: Tabellenform gibt es nur für `type = \"quiz\"` und `type = \"guess\"`"
                    )));
                }
                if !quiz.accept.is_empty() {
                    return Err(invalid(format!("{where_}: `accept` gibt es nur bei Guess")));
                }
                let short = !quiz.correct.is_empty() || !quiz.wrong.is_empty();
                if short == !quiz.options.is_empty() {
                    return Err(invalid(format!(
                        "{where_}: Quiz entweder mit `correct`/`wrong` oder mit `options`"
                    )));
                }
                let options = if short {
                    quiz.correct
                        .iter()
                        .map(|t| QuizOption {
                            text: t.clone(),
                            correct: true,
                        })
                        .chain(quiz.wrong.iter().map(|t| QuizOption {
                            text: t.clone(),
                            correct: false,
                        }))
                        .collect()
                } else {
                    quiz.options.clone()
                };
                Answer {
                    kind: AnswerKind::Quiz,
                    options,
                    ..Answer::default()
                }
            }
        };
        answer
            .validate()
            .map_err(|e| invalid(format!("{where_}: {e}")))?;
        Ok(answer)
    }

    fn from_answer(answer: &Answer) -> Option<Self> {
        match answer.kind {
            AnswerKind::Recall => None,
            AnswerKind::Guess if answer.accept.is_empty() => {
                Some(AnswerSource::Kind("guess".into()))
            }
            AnswerKind::Guess => Some(AnswerSource::Quiz(QuizSource {
                kind: "guess".into(),
                correct: Vec::new(),
                wrong: Vec::new(),
                options: Vec::new(),
                accept: answer.accept.clone(),
            })),
            AnswerKind::Quiz => {
                // Keep the short form when it reproduces the exact order.
                let split = answer
                    .options
                    .iter()
                    .position(|o| !o.correct)
                    .unwrap_or(answer.options.len());
                let ordered = answer.options[split..].iter().all(|o| !o.correct);
                Some(AnswerSource::Quiz(if ordered {
                    QuizSource {
                        kind: "quiz".into(),
                        correct: answer.options[..split]
                            .iter()
                            .map(|o| o.text.clone())
                            .collect(),
                        wrong: answer.options[split..]
                            .iter()
                            .map(|o| o.text.clone())
                            .collect(),
                        options: Vec::new(),
                        accept: Vec::new(),
                    }
                } else {
                    QuizSource {
                        kind: "quiz".into(),
                        correct: Vec::new(),
                        wrong: Vec::new(),
                        options: answer.options.clone(),
                        accept: Vec::new(),
                    }
                }))
            }
        }
    }
}

impl TableSource {
    fn to_row(&self) -> Result<Row> {
        let cells = match (&self.value, self.cells.is_empty()) {
            (Some(value), true) => vec![Cell {
                column: "value".into(),
                kind: self.kind.unwrap_or(CellType::Text),
                value: value.clone(),
            }],
            (None, false) if self.kind.is_none() => self.cells.clone(),
            _ => {
                return Err(invalid(format!(
                    "Tabelle {}.{}: entweder `value` (mit optionalem `type`) oder `cells`",
                    self.table, self.key
                )));
            }
        };
        let row = Row {
            table: self.table.clone(),
            key: self.key.clone(),
            cells,
        };
        row.validate()
            .map_err(|e| invalid(format!("Tabelle {}.{}: {}", self.table, self.key, e.0)))?;
        Ok(row)
    }

    fn from_row(row: &Row) -> Self {
        match row.cells.as_slice() {
            [cell] if cell.column == "value" => TableSource {
                table: row.table.clone(),
                key: row.key.clone(),
                value: Some(cell.value.clone()),
                kind: (cell.kind != CellType::Text).then_some(cell.kind),
                cells: Vec::new(),
            },
            cells => TableSource {
                table: row.table.clone(),
                key: row.key.clone(),
                value: None,
                kind: None,
                cells: cells.to_vec(),
            },
        }
    }
}

// ---------------------------------------------------------------- checking

/// A fully checked source, ready to write into a store.
#[derive(Debug, Clone, PartialEq)]
pub struct Plan {
    pub name: String,
    /// Custom locus marker file.
    pub marker: Option<MediaFile>,
    pub rooms: Vec<PlannedRoom>,
    pub tables: Vec<Row>,
}

/// A media file on disk and its media type.
pub type MediaFile = (PathBuf, &'static str);

#[derive(Debug, Clone, PartialEq)]
pub struct PlannedRoom {
    pub name: String,
    pub kind: RoomKind,
    /// Backdrop file and its media type.
    pub media: Option<MediaFile>,
    /// Each locus with its bindings and optional picture file.
    pub loci: Vec<(NewLocus, Vec<Binding>, Option<MediaFile>)>,
}

impl Plan {
    pub fn loci(&self) -> usize {
        self.rooms.iter().map(|r| r.loci.len()).sum()
    }
}

/// Parse `locora.toml` text.
pub fn parse(text: &str) -> Result<Source> {
    Ok(toml::from_str(text)?)
}

/// Check a source completely (files, times, answers, formulas, tables) without writing anything.
/// Relative media paths are resolved against `base`.
pub fn check(source: &Source, base: &Path) -> Result<Plan> {
    let name = source.name.trim();
    if name.is_empty() {
        return Err(invalid("`name` darf nicht leer sein"));
    }
    if source.rooms.is_empty() {
        return Err(invalid("Ein Palast braucht mindestens einen `[[room]]`"));
    }
    let mut number = 0;
    let mut rooms = Vec::new();
    for (r, room) in source.rooms.iter().enumerate() {
        let where_room = format!("Raum {} („{}“)", r + 1, room.name);
        if room.name.trim().is_empty() {
            return Err(invalid(format!("Raum {}: `name` fehlt", r + 1)));
        }
        let media = match (&room.image, &room.video) {
            (Some(_), Some(_)) => {
                return Err(invalid(format!(
                    "{where_room}: entweder `image` oder `video`"
                )));
            }
            (Some(file), None) | (None, Some(file)) => {
                let path = base.join(file);
                let (kind, media_type) = media_type(&path)
                    .ok_or_else(|| invalid(format!("{where_room}: {file}: unbekanntes Format (png, jpg, webp, gif, avif, mp4, webm, mov)")))?;
                let wanted = if room.video.is_some() {
                    RoomKind::Video
                } else {
                    RoomKind::Image
                };
                if kind != wanted {
                    let what = if wanted == RoomKind::Video {
                        "kein Video"
                    } else {
                        "kein Bild"
                    };
                    return Err(invalid(format!("{where_room}: {file} ist {what}")));
                }
                check_file(&path, media_type, &where_room)?;
                Some((path, media_type))
            }
            (None, None) => None,
        };
        let kind = media
            .as_ref()
            .map_or(RoomKind::Blank, |(p, _)| media_type(p).expect("checked").0);
        if !room.items.is_empty() && !room.loci.is_empty() {
            return Err(invalid(format!(
                "{where_room}: entweder `items` (Kurzform) oder `[[room.locus]]`"
            )));
        }
        let loci_src: Vec<LocusSource> = if room.items.is_empty() {
            room.loci.clone()
        } else {
            room.items
                .iter()
                .map(|i| LocusSource {
                    item: i.clone(),
                    ..Default::default()
                })
                .collect()
        };
        let spots = places::route(loci_src.len());
        let mut loci = Vec::new();
        for (i, locus) in loci_src.iter().enumerate() {
            number += 1;
            let where_ = format!("{where_room}, Locus {}", i + 1);
            if locus.item.trim().is_empty() {
                return Err(invalid(format!("{where_}: `item` ist leer")));
            }
            let (x, y) = match locus.at {
                Some([x, y]) if (0.0..=1.0).contains(&x) && (0.0..=1.0).contains(&y) => (x, y),
                Some(_) => {
                    return Err(invalid(format!(
                        "{where_}: `at` muss zwischen [0, 0] und [1, 1] liegen"
                    )));
                }
                None => spots[i],
            };
            let time = match &locus.time {
                None => None,
                Some(TimeSource::Seconds(s)) if s.is_finite() && *s >= 0.0 => Some(*s),
                Some(TimeSource::Clock(text)) => Some(parse_time(text).ok_or_else(|| {
                    invalid(format!(
                        "{where_}: Zeit „{text}“ (erwartet m:ss oder Sekunden)"
                    ))
                })?),
                Some(_) => return Err(invalid(format!("{where_}: ungültige Zeit"))),
            };
            match (kind == RoomKind::Video, time.is_some()) {
                (true, false) => {
                    return Err(invalid(format!(
                        "{where_}: im Video-Raum braucht jeder Locus `time`"
                    )));
                }
                (false, true) => {
                    return Err(invalid(format!(
                        "{where_}: `time` gibt es nur in Video-Räumen"
                    )));
                }
                _ => {}
            }
            let answer = match &locus.answer {
                Some(a) => a.to_answer(&where_)?,
                None => Answer::default(),
            };
            let mut bindings = Vec::new();
            for (field, expression) in &locus.bindings {
                let field = BindingField::parse(field)
                    .map_err(|e| invalid(format!("{where_}: {}", e.0)))?;
                let binding = Binding {
                    field,
                    expression: expression.clone(),
                };
                binding.validate().map_err(|e| {
                    invalid(format!("{where_}: Formel für {}: {}", field.name(), e.0))
                })?;
                bindings.push(binding);
            }
            locora_store::check_image_size(locus.image_size)
                .map_err(|e| invalid(format!("{where_}: {e}")))?;
            locora_store::check_zoom(locus.zoom).map_err(|e| invalid(format!("{where_}: {e}")))?;
            let picture = match &locus.image {
                Some(file) => Some(check_picture(base, file, &where_)?),
                None => None,
            };
            loci.push((
                NewLocus {
                    place: locus
                        .place
                        .clone()
                        .filter(|p| !p.trim().is_empty())
                        .unwrap_or_else(|| format!("Ort {number}")),
                    item: locus.item.clone(),
                    x,
                    y,
                    time,
                    answer,
                    image: None,
                    image_size: locus.image_size,
                    zoom: locus.zoom,
                    note: locus.note.clone().unwrap_or_default(),
                },
                bindings,
                picture,
            ));
        }
        rooms.push(PlannedRoom {
            name: room.name.trim().into(),
            kind,
            media,
            loci,
        });
    }
    let mut tables = Vec::new();
    for t in &source.tables {
        let row = t.to_row()?;
        if tables
            .iter()
            .any(|r: &Row| r.table == row.table && r.key == row.key)
        {
            return Err(invalid(format!(
                "Tabelle {}.{} ist doppelt",
                row.table, row.key
            )));
        }
        tables.push(row);
    }
    let marker = match &source.marker {
        None => None,
        Some(file) => {
            let path = base.join(file);
            if media_type(&path).map(|(_, t)| t) != Some(locora_store::SPLINELY) {
                return Err(invalid(format!(
                    "`marker`: {file} muss eine .sply-Datei sein"
                )));
            }
            check_file(&path, locora_store::SPLINELY, "`marker`")?;
            Some((path, locora_store::SPLINELY))
        }
    };
    Ok(Plan {
        name: name.into(),
        marker,
        rooms,
        tables,
    })
}

// ---------------------------------------------------------------- building

/// Write a checked plan into the store as a new palace. If anything fails
/// half-way, the partly built palace is removed again.
pub fn build(store: &Store, plan: &Plan) -> Result<PalaceTree> {
    if store.find_palace(&plan.name)?.is_some() {
        return Err(invalid(format!(
            "Es gibt schon einen Palast „{}“",
            plan.name
        )));
    }
    let palace = store.create_palace(&plan.name)?;
    let result = (|| -> Result<()> {
        if let Some((path, media_type)) = &plan.marker {
            let bytes =
                fs::read(path).map_err(|e| SourceError::File(path.display().to_string(), e))?;
            let hash = store.put_media(&bytes, media_type)?.hash;
            store.set_marker(&palace.id, Some(&hash))?;
        }
        for row in &plan.tables {
            store.set_row(Some(&palace.id), row)?;
        }
        for room in &plan.rooms {
            let media = match &room.media {
                Some((path, media_type)) => {
                    let bytes = fs::read(path)
                        .map_err(|e| SourceError::File(path.display().to_string(), e))?;
                    Some(store.put_media(&bytes, media_type)?.hash)
                }
                None => None,
            };
            let created = store.add_room(&palace.id, &room.name, room.kind, media.as_deref())?;
            for (locus, bindings, picture) in &room.loci {
                let mut locus = locus.clone();
                if let Some((path, media_type)) = picture {
                    let bytes = fs::read(path)
                        .map_err(|e| SourceError::File(path.display().to_string(), e))?;
                    locus.image = Some(store.put_media(&bytes, media_type)?.hash);
                }
                let new = store.add_locus(&created.id, locus)?;
                for binding in bindings {
                    store.set_binding(&new.id, binding)?;
                }
            }
        }
        Ok(())
    })();
    if let Err(err) = result {
        let _ = store.delete_palace(&palace.id);
        return Err(err);
    }
    Ok(store.palace(&palace.id)?)
}

// ---------------------------------------------------------------- dumping

fn slug(name: &str) -> String {
    let s: String = name
        .chars()
        .map(|c| {
            if c.is_alphanumeric() {
                c.to_ascii_lowercase()
            } else {
                '-'
            }
        })
        .collect();
    let s = s
        .split('-')
        .filter(|p| !p.is_empty())
        .collect::<Vec<_>>()
        .join("-");
    if s.is_empty() { "palast".into() } else { s }
}

fn clock(seconds: f64) -> TimeSource {
    if seconds.fract() == 0.0 {
        let s = seconds as u64;
        TimeSource::Clock(if s >= 3600 {
            format!("{}:{:02}:{:02}", s / 3600, s % 3600 / 60, s % 60)
        } else {
            format!("{}:{:02}", s / 60, s % 60)
        })
    } else {
        TimeSource::Seconds(seconds)
    }
}

/// The source form of a stored palace. Media is referenced by file names
/// chosen per room (see [`dump`]).
pub fn to_source(tree: &PalaceTree, media_names: &HashMap<String, String>) -> Source {
    Source {
        name: tree.palace.name.clone(),
        marker: tree.palace.marker.as_ref().map(|h| media_names[h].clone()),
        rooms: tree
            .rooms
            .iter()
            .map(|r| {
                let file = r.room.media.as_ref().map(|h| media_names[h].clone());
                RoomSource {
                    name: r.room.name.clone(),
                    image: file.clone().filter(|_| r.room.kind == RoomKind::Image),
                    video: file.filter(|_| r.room.kind == RoomKind::Video),
                    items: Vec::new(),
                    loci: r
                        .loci
                        .iter()
                        .map(|l| LocusSource {
                            place: Some(l.place.clone()),
                            item: l.item.clone(),
                            at: Some([l.x, l.y]),
                            time: l.time.map(clock),
                            answer: AnswerSource::from_answer(&l.answer),
                            image: l.image.as_ref().map(|h| media_names[h].clone()),
                            image_size: l.image_size,
                            zoom: l.zoom,
                            note: (!l.note.is_empty()).then(|| l.note.clone()),
                            bindings: l
                                .bindings
                                .iter()
                                .map(|b| (b.field.name().to_owned(), b.expression.clone()))
                                .collect(),
                        })
                        .collect(),
                }
            })
            .collect(),
        tables: tree.tables.iter().map(TableSource::from_row).collect(),
    }
}

/// Write a palace as `<dir>/<name>.locora.toml` plus its media files.
/// Existing files are never overwritten.
pub fn dump(store: &Store, query: &str, dir: &Path) -> Result<PathBuf> {
    let tree = store.palace(query)?;
    fs::create_dir_all(dir).map_err(|e| SourceError::File(dir.display().to_string(), e))?;
    let target = dir.join(format!("{}.locora.toml", slug(&tree.palace.name)));
    let mut names: HashMap<String, String> = HashMap::new();
    let mut writes: Vec<(PathBuf, PathBuf)> = Vec::new();
    // Backdrops are named after their room, pictures after their place.
    let files = tree
        .rooms
        .iter()
        .filter_map(|r| r.room.media.as_ref().map(|h| (h, r.room.name.as_str())))
        .chain(
            tree.route()
                .filter_map(|l| l.image.as_ref().map(|h| (h, l.place.as_str()))),
        )
        .chain(tree.palace.marker.as_ref().map(|h| (h, "marker")));
    for (hash, label) in files {
        if names.contains_key(hash) {
            continue;
        }
        let media = store
            .media(hash)?
            .ok_or_else(|| invalid(format!("Medium {hash} fehlt")))?;
        let mut name = format!("{}.{}", slug(label), extension_of(&media.mime));
        let mut n = 2;
        while names.values().any(|v| *v == name) {
            name = format!("{}-{n}.{}", slug(label), extension_of(&media.mime));
            n += 1;
        }
        let from = store
            .media_file(hash)
            .ok_or_else(|| invalid("dieser Speicher hat keine Mediendateien"))?;
        writes.push((from, dir.join(&name)));
        names.insert(hash.clone(), name);
    }
    for path in std::iter::once(&target).chain(writes.iter().map(|(_, to)| to)) {
        if path.exists() {
            return Err(invalid(format!("{} gibt es schon", path.display())));
        }
    }
    for (from, to) in &writes {
        fs::copy(from, to).map_err(|e| SourceError::File(to.display().to_string(), e))?;
    }
    let text = toml::to_string_pretty(&to_source(&tree, &names))
        .map_err(|e| invalid(format!("TOML schreiben: {e}")))?;
    fs::write(&target, text).map_err(|e| SourceError::File(target.display().to_string(), e))?;
    Ok(target)
}

